"""MathType 公式解析、Word 试卷导入的辅助函数。"""

from tools import mtef, mtef_latex
from tools.import_user_docs import fix_functions, solution_text, split_part_answers, strip_dollars, table_tex

# 取自一份 Word 试卷里的真实公式对象（"Equation Native" 流）
SAMPLE_PLAIN = bytes.fromhex("")  # (1+5i)i
SAMPLE_FRAC = bytes.fromhex("")  # y=2tan(x-π/3)


def latex(data: bytes) -> str:
    return mtef_latex.to_latex(mtef.parse(data))


def test_mtef_plain_and_fraction():
    assert latex(SAMPLE_PLAIN) == "(1+5i)i"
    assert latex(SAMPLE_FRAC) == "y=2\\tan \\left(x-\\frac{\\pi }{3}\\right)"


def test_fix_functions_adds_backslash_only_in_math():
    assert fix_functions("$sinx+cos\\alpha$ sin") == "$\\sin x+\\cos \\alpha$ sin"
    assert fix_functions("$\\text{sin}$") == "$\\text{sin}$"


def test_table_and_answers():
    assert table_tex(["a\tb", "1\t$x$"]).startswith("$$\\begin{array}{|c|c|}")
    assert strip_dollars("$\\frac{61}{25}$##$2.44$") == "\\frac{61}{25}"
    assert split_part_answers("（1）证明见解析；（2）$3$") == ["证明见解析", "$3$"]
    assert solution_text("【分析】甲【详解】乙").startswith("思路：甲")
